package com.javatpoint.servlets;
import java.io.IOException;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import com.javatpoint.beans.IssueBookBean;import com.javatpoint.dao.BookDao;import com.javatpoint.util.AuthUtil;
@WebServlet("/IssueBook") public class IssueBook extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{if(!AuthUtil.requireLibrarian(req,res))return;try{long m=Long.parseLong(req.getParameter("studentmobile"));IssueBookBean b=new IssueBookBean(req.getParameter("callno"),req.getParameter("studentid"),req.getParameter("studentname"),m);if(BookDao.issueBook(b)>0)res.sendRedirect("ViewIssuedBook");else res.sendError(409,"Book is unavailable or the issue request is invalid.");}catch(NumberFormatException e){res.sendError(400,"Student mobile must contain digits only.");}}}